const raw = $input.first().json;
const i = raw.body || raw;
return [{ json: { store_id: i.store_id||1, customer_id: i.customer_id||i.customerId||null, order_id: i.order_id||i.orderId||null, type: i.type||'GENERAL', severity: i.severity||'normal', description: (i.description||i.message||'').replace(/'/g,"''").substring(0,2000), customer_email: i.email||i.customer_email||null } }];

const d = $('Normalize').first().json;
const severity = d.severity;
const store_id = d.store_id;
const type = d.type;
let alert_sql = '';
if (severity === 'critical') {
  alert_sql = `INSERT INTO alerts (store_id, type, severity, message, is_read, is_sent, created_at) VALUES (${store_id}, 'SAV_CRITICAL', 'critical', 'URGENT SAV: ${type}', false, false, NOW());`;
} else if (severity === 'high') {
  alert_sql = `INSERT INTO alerts (store_id, type, severity, message, is_read, is_sent, created_at) VALUES (${store_id}, 'SAV_HIGH', 'high', 'SAV High: ${type}', false, false, NOW());`;
}
return [{ json: { store_id, severity, type, alert_sql, has_alert: alert_sql !== '' } }];
